(()=>{'use strict';const root=document.documentElement,button=document.getElementById('sidebar-toggle'),sidebar=document.getElementById('workspace-sidebar');if(!button||!sidebar)return;for(const item of sidebar.querySelectorAll('.nav-item')){const label=document.createElement('span');label.className='nav-label';for(const node of [...item.childNodes])if(node.nodeType===3)label.append(node);item.insertBefore(label,item.querySelector('.nav-count'));item.title=label.textContent.trim();item.setAttribute('aria-label',label.textContent.trim())}let preference;try{preference=localStorage.getItem('nova-sidebar-collapsed')}catch{}const mobile=matchMedia('(max-width:600px)');function set(collapsed,save=false){root.classList.toggle('sidebar-collapsed',collapsed);button.setAttribute('aria-expanded',String(!collapsed));button.setAttribute('aria-label',collapsed?'Expand navigation':'Collapse navigation');button.title=button.getAttribute('aria-label');sidebar.inert=mobile.matches&&collapsed;if(save)try{localStorage.setItem('nova-sidebar-collapsed',String(collapsed))}catch{}}set(preference===null||preference===undefined?mobile.matches:preference==='true');button.addEventListener('click',()=>set(!root.classList.contains('sidebar-collapsed'),true));sidebar.addEventListener('click',event=>{if(mobile.matches&&event.target.closest('.nav-item')){set(true);button.focus()}});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&mobile.matches&&!root.classList.contains('sidebar-collapsed')){set(true);button.focus()}});mobile.addEventListener('change',()=>set(mobile.matches));})();

/* Public ReactVibe patterns adapted to the existing vanilla CRM. No PRO source. */
(()=>{'use strict';const doc=document,nav=doc.getElementById('navigation'),tools=doc.querySelector('.topbar-tools');if(!nav||!tools)return;
const groups={overview:'Workspace',players:'Community',licenses:'Customers',kanban:'Customers',finance:'Operations',leaderboards:'Community',versions:'Operations',network:'Operations',kog:'Community',titles:'Community'};let previous='';for(const item of [...nav.querySelectorAll('[data-view]')]){const group=groups[item.dataset.view]||'Operations';if(group!==previous){const heading=doc.createElement('span');heading.className='navigation-section';heading.textContent=group;nav.insertBefore(heading,item);previous=group;}}
const open=doc.createElement('button');open.type='button';open.className='workspace-command-trigger';open.textContent='Search workspace';const hint=doc.createElement('kbd');hint.textContent=/Mac/.test(navigator.platform)?'⌘ K':'Ctrl K';open.append(hint);open.setAttribute('aria-haspopup','dialog');tools.prepend(open);
const dialog=doc.createElement('dialog');dialog.className='workspace-command';dialog.setAttribute('aria-label','Search workspace navigation');const header=doc.createElement('div');header.className='command-header';const input=doc.createElement('input');input.type='search';input.placeholder='Find a workspace page…';input.setAttribute('aria-label','Find a workspace page');const close=doc.createElement('button');close.type='button';close.textContent='Close';header.append(input,close);const results=doc.createElement('div');results.className='command-results';const empty=doc.createElement('p');empty.textContent='No matching pages. Try another name.';empty.hidden=true;dialog.append(header,results,empty);doc.body.append(dialog);
function render(){results.replaceChildren();const query=input.value.trim().toLowerCase();for(const item of nav.querySelectorAll('[data-view]')){if(item.hidden||item.closest('[hidden]'))continue;const label=item.getAttribute('aria-label')||item.textContent.trim();if(!label.toLowerCase().includes(query))continue;const button=doc.createElement('button');button.type='button';button.textContent=label;button.addEventListener('click',()=>{dialog.close();item.click();const heading=doc.querySelector('.page-heading h1');if(heading){heading.tabIndex=-1;heading.focus()}});results.append(button)}empty.hidden=results.childElementCount>0;}
let origin;function show(){if(doc.getElementById('app')?.hidden)return;origin=doc.activeElement;input.value='';render();dialog.showModal();input.focus()}open.addEventListener('click',show);close.addEventListener('click',()=>dialog.close());input.addEventListener('input',render);input.addEventListener('keydown',event=>{if(event.key==='ArrowDown'){event.preventDefault();results.querySelector('button')?.focus()}if(event.key==='Enter'){event.preventDefault();results.querySelector('button')?.click()}});results.addEventListener('keydown',event=>{const buttons=[...results.querySelectorAll('button')],index=buttons.indexOf(doc.activeElement);if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();buttons[(index+(event.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus()}});dialog.addEventListener('close',()=>origin?.focus());doc.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'&&!event.repeat){event.preventDefault();if(dialog.open)dialog.close();else show()}});
})();
